(window.LAW_DATA = window.LAW_DATA || {})["fzpdd"] = {"items":[{"h":"Глава I. Общие положения"},{"n":"Статья 1.1","title":"","text":"Настоящие Правила дорожного движения (в дальнейшем - Правила) устанавливают единый порядок дорожного движения на всей территории Российской Федерации. Другие нормативные правовые акты, касающиеся дорожного движения, должны основываться на требованиях Правил и не противоречить им."},{"n":"Статья 1.2","title":"","sub":[{"n":"1)","text":"велосипедист - лицо, управляющее велосипедом;","lvl":1},{"n":"2)","text":"водитель - лицо, управляющее каким-либо транспортным средством, погонщик, ведущий по дороге вьючных, верховых животных или стадо. К водителю приравнивается обучающий вождению;","lvl":1},{"n":"3)","text":"вынужденная остановка - прекращение движения транспортного средства из-за его технической неисправности или опасности, создаваемой перевозимым грузом, состоянием водителя (пассажира) или появлением препятствия на дороге;","lvl":1},{"n":"4)","text":"государственная инспекция безопасности дорожного движения (ГИБДД) - орган министерства внутренних дел, на который возложено обеспечение безопасности дорожного движения;","lvl":1},{"n":"5)","text":"дорога - обустроенная или приспособленная и используемая для движения транспортных средств полоса земли либо поверхность искусственного сооружения. Дорога включает в себя одну или несколько проезжих частей;","lvl":1},{"n":"6)","text":"дорожное движение - совокупность общественных отношений, возникающих в процессе перемещения людей и грузов с помощью транспортных средств или без таковых в пределах дорог;","lvl":1},{"n":"7)","text":"дорожно-патрульная служба (ДПС) - структурное подразделение Главного управления по обеспечению безопасности дорожного движения;","lvl":1},{"n":"8)","text":"дорожно-транспортное происшествие (ДТП) - событие, возникшее в процессе движения по дороге транспортного средства и с его участием, при котором погибли или ранены люди, повреждены транспортные средства, сооружения, грузы либо причинен иной материальный ущерб;","lvl":1},{"n":"9)","text":"обгон - опережение одного или нескольких транспортных средств, связанное с выездом на полосу, предназначенную для встречного движения, и последующим возвращением на ранее занимаемую полосу;","lvl":1},{"n":"10)","text":"обочина - элемент дороги, примыкающий непосредственно к проезжей части, отличающийся типом покрытия или выделенный с помощью разметки;","lvl":1},{"n":"11)","text":"опасность для движения - ситуация, возникшая в процессе дорожного движения, при которой продолжение движения в том же направлении и с той же скоростью создает угрозу возникновения дорожно-транспортного происшествия;","lvl":1},{"n":"12)","text":"опережение - движение транспортного средства со скоростью, большей скорости попутного транспортного средства;","lvl":1},{"n":"13)","text":"остановка - преднамеренное прекращение движения транспортного средства на время до 5 минут;","lvl":1},{"n":"14)","text":"парковочное место (Парковка) - специально обозначенное и при необходимости обустроенное и оборудованное место, предназначенное для организованной стоянки транспортных средств;","lvl":1},{"n":"15)","text":"перекресток - место пересечения, примыкания или разветвления дорог на одном уровне, ограниченное воображаемыми линиями. Не считаются перекрестками выезды с прилегающих территорий;","lvl":1},{"n":"16)","text":"пешеход - лицо, находящееся вне транспортного средства на дороге либо на пешеходной дорожке;","lvl":1},{"n":"17)","text":"преимущество (приоритет) - право на первоочередное движение в намеченном направлении по отношению к другим участникам движения;","lvl":1},{"n":"18)","text":"регулировщик - сотрудник ДПС, осуществляющий регулирование дорожного движения;","lvl":1},{"n":"19)","text":"стоянка - преднамеренное прекращение движения транспортного средства на время более 5 минут;","lvl":1},{"n":"20)","text":"транспортное средство (ТС) - устройство, предназначенное для перевозки по дорогам людей, грузов или оборудования, установленного на нем;","lvl":1},{"n":"21)","text":"тротуар - элемент дороги, предназначенный для движения пешеходов и примыкающий к проезжей части или к велосипедной дорожке либо отделенный от них газоном;","lvl":1},{"n":"22)","text":"эксплуатация транспортного средства - использование транспортного средства для движения.","lvl":1},{"n":"23)","text":"перестроение - выезд из занимаемой полосы или занимаемого ряда с сохранением первоначального направления движения.","lvl":1},{"n":"24)","text":"прилегающая территория - территория, непосредственно прилегающая к дороге и не предназначенная для сквозного движения транспортных средств (дворы, жилые массивы, автостоянки, АЗС, предприятия и тому подобное). Движение по прилегающей территории осуществляется в соответствии с настоящими Правилами;","lvl":1},{"n":"25)","text":"проезжая часть - элемент дороги, предназначенный для движения безрельсовых транспортных средств;","lvl":1}],"text":"В Правилах используются следующие основные понятия и термины:"},{"n":"Статья 1.3","title":"","sub":[{"n":"1.3.1","text":"Участники дорожного движения обязаны знать и соблюдать относящиеся к ним требования Правил, сигналов светофоров, знаков и разметки, а также выполнять распоряжения регулировщиков, действующих в пределах предоставленных им прав и регулирующих дорожное движение."},{"n":"1.3.2","text":"Участники дорожного движения обязаны соблюдать требования, установленные с учётом решений Конституционного Суда Российской Федерации."}]},{"n":"Статья 1.4","title":"","text":"Лица, нарушившие Правила, несут ответственность в соответствии с законодательством Российской Федерации."},{"n":"Статья 1.5","title":"","text":"Под опасным вождением понимается управление транспортным средством, выражающееся в неоднократном совершении одного или совершении нескольких следующих друг за другом действий, заключающихся в невыполнении при перестроении требования уступить дорогу транспортному средству, пользующемуся преимущественным правом движения, перестроении при интенсивном движении, когда все полосы движения заняты, кроме случаев поворота налево или направо, разворота, остановки или объезда препятствия, несоблюдении безопасной дистанции до движущегося впереди транспортного средства, несоблюдении бокового интервала, резком торможении, если такое торможение не требуется для предотвращения дорожно-транспортного происшествия, препятствовании обгону, если указанные действия повлекли создание водителем в процессе дорожного движения ситуации, при которой его движение и (или) движение иных участников дорожного движения в том же направлении и с той же скоростью создает угрозу гибели или ранения людей, повреждения транспортных средств, сооружений, грузов или причинения иного материального ущерба."},{"n":"Статья 1.6","title":"","text":"На дорогах установлено правостороннее движение транспортных средств."},{"h":"Глава II. Обязанности водителей и пассажиров"},{"n":"Статья 2.1","title":"","sub":[{"n":"а)","text":"водительское удостоверение;","lvl":1},{"n":"б)","text":"технический паспорт транспортного средства;","lvl":1},{"n":"в)","text":"разрешение на управление транспортным средством (в случае временного пользования, документ пишется от имени владельца).","lvl":1}],"text":"Водитель транспортного средства обязан иметь при себе и по требованию сотрудников ГИБДД передавать им для проверки:"},{"n":"Статья 2.2","title":"","sub":[{"n":"а)","text":"быть пристегнутым и не перевозить пассажиров, не пристегнутых ремнями;","lvl":1},{"n":"б)","text":"перед выездом проверить и в пути обеспечить исправное техническое состояние транспортного средства в соответствии со статьей 13.1 Правил.","lvl":1},{"n":"в)","text":"в случаях предусмотренных статьей 15.2 Правил водитель обязан покинуть транспортное средство и не отходить дальше чем на 15 метров от места остановки, согласно выдвинутому устному требованию сотрудником Государственной Инспекции Безопасности Дорожного Движения, если таковое требование законно и обосновано.","lvl":1}],"text":"Водитель транспортного средства обязан:"},{"n":"Статья 2.3","title":"","text":"По требованию сотрудника ГИБДД водитель обязан проходить освидетельствование на состояние алкогольного опьянения."},{"n":"Статья 2.4","title":"","sub":[{"n":"а)","text":"в состоянии опьянения (алкогольного, наркотического или иного), под воздействием лекарственных препаратов, ухудшающих реакцию и внимание, в болезненном или утомленном состоянии, ставящем под угрозу безопасность движения;","lvl":1},{"n":"б)","text":"в случае отсутствия у него действующего водительского удостоверения.","lvl":1}],"text":"Водителю запрещается управлять транспортным средством:"},{"n":"Статья 2.5","title":"","text":"Водитель обязан соблюдать настоящие Правила. Водитель обязан выполнять требования сотрудников ГИБДД в пределах их полномочий по ведению надзора в сфере безопасности дорожного движения."},{"n":"Статья 2.6","title":"","text":"При дорожно-транспортном происшествии (далее - ДТП) водитель, причастный к нему, обязан незамедлительно остановить (не трогать с места) транспортное средство, включить аварийную сигнализацию и выставить знак аварийной остановки, не перемещать предметы, имеющие отношение к происшествию, после чего вызвать сотрудников дорожно-патрульной службы. Дальнейшие действия водителя определяются сотрудниками ГИБДД."},{"n":"Статья 2.7","title":"","sub":[{"n":"а)","text":"при поездке на транспортном средстве, оборудованном ремнями безопасности, быть пристегнутыми ими, а при поездке на мотоцикле - быть в застегнутом мотошлеме;","lvl":1},{"n":"б)","text":"посадку и высадку производить со стороны тротуара или обочины и только после полной остановки транспортного средства.","lvl":1},{"n":"","text":"Если посадка и высадка невозможна со стороны тротуара или обочины, она может осуществляться со стороны проезжей части при условии, что это будет безопасно и не создаст помех другим участникам движения."}],"text":"Пассажиры обязаны:"},{"n":"Статья 2.8","title":"","sub":[{"n":"а)","text":"отвлекать водителя от управления транспортным средством во время его движения;","lvl":1},{"n":"б)","text":"при поездке на грузовом автомобиле с бортовой платформой стоять, сидеть на бортах или на грузе выше бортов;","lvl":1},{"n":"в)","text":"открывать двери транспортного средства во время его движения.","lvl":1}],"text":"Пассажирам запрещается:"},{"h":"Глава III. Применение специальных, аварийных и звуковых сигналов, световых приборов"},{"n":"Статья 3.1","title":"","text":"Водители транспортных средств с включенным проблесковым маячком синего цвета, выполняя неотложное служебное задание, могут отступать от требований главы 5 (кроме сигналов регулировщика) и иных глав настоящих Правил. Для получения преимущества перед другими участниками движения водители таких транспортных средств должны включить проблесковый маячок синего цвета и специальный звуковой сигнал. Воспользоваться приоритетом они могут только убедившись, что им уступают дорогу. Этим же правом пользуются водители транспортных средств, сопровождаемых транспортными средствами, имеющими нанесенные на наружные поверхности специальные цветографические схемы, с включенными проблесковыми маячками синего и красного цветов и специальным звуковым сигналом, в случаях, установленных настоящей статьей."},{"n":"Статья 3.2","title":"","text":"При приближении транспортного средства с включенными проблесковым маячком синего цвета и специальным звуковым сигналом водители обязаны уступить дорогу для обеспечения беспрепятственного проезда указанного транспортного средства. При приближении транспортного средства, имеющего нанесенные на наружные поверхности специальные цветографические схемы, с включенными проблесковыми маячками синего и красного цветов и специальным звуковым сигналом водители обязаны уступить дорогу для обеспечения беспрепятственного проезда указанного транспортного средства, а также сопровождаемого им транспортного средства (сопровождаемых транспортных средств). Запрещается выполнять обгон транспортного средства, имеющего нанесенные на наружные поверхности специальные цветографические схемы с включенными проблесковым маячком синего цвета и специальным звуковым сигналом."},{"n":"Статья 3.3","title":"","text":"Приближаясь к стоящему транспортному средству с включенным проблесковым маячком синего цвета, водитель должен снизить скорость, чтобы иметь возможность немедленно остановиться в случае необходимости."},{"n":"Статья 3.4","title":"","sub":[{"n":"а)","text":"выполнение работ по строительству, ремонту или содержанию дорог, погрузке поврежденных, неисправных и перемещаемых транспортных средств;","lvl":1},{"n":"б)","text":"движение крупногабаритных транспортных средств, а также перевозка грузов повышенной опасности;","lvl":1},{"n":"в)","text":"сопровождение тяжеловесных и (или) крупногабаритных транспортных средств, а также транспортных средств, осуществляющих перевозки опасных грузов;","lvl":1},{"n":"г)","text":"сопровождение организованных групп велосипедистов при проведении тренировочных мероприятий на автомобильных дорогах общего пользования.","lvl":1},{"n":"","text":"Включенный проблесковый маячок желтого или оранжевого цвета не дает преимущества в движении и служит для предупреждения других участников движения об опасности."}],"text":"Проблесковый маячок желтого или оранжевого цвета должен быть включен на транспортных средствах в следующих случаях:"},{"n":"Статья 3.5","title":"","sub":[{"n":"а)","text":"выезда на вызов, место происшествия, место проведения специальных операций;","lvl":1},{"n":"б)","text":"транспортировки задержанных в орган дознания и/или место заключения под стражу;","lvl":1},{"n":"в)","text":"транспортировки больных, раненых сотрудниками медицинских организаций в городскую больницу;","lvl":1},{"n":"г)","text":"патрулирования дорог, надзора за безопасностью дорожного движения сотрудниками ГИБДД;","lvl":1},{"n":"д)","text":"исполнения иных обязанностей, предусмотренных законодательством.","lvl":1}],"text":"Использовать специальные сигналы разрешается, в случае:"},{"n":"Статья 3.6","title":"","sub":[{"n":"а)","text":"нарушение скоростного режима, не более чем на 80 км/ч от установленного.","lvl":1},{"n":"б)","text":"нарушение дорожной разметки;","lvl":1},{"n":"в)","text":"нарушение правил остановки и стоянки, в случае если не является возможным осуществить правильную остановку и стоянку ТС;","lvl":1},{"n":"г)","text":"нарушения дистанции движения ТС;","lvl":1},{"n":"д)","text":"нарушения обгона ТС.","lvl":1},{"n":"","text":"Примечание: для сотрудников ГИБДД ограничение отсутствует во время преследования транспортного средства, нарушающего Правила, в целях его остановки;"}],"text":"В случае использования проблесковых маячков синего цвета разрешаются незначительные нарушения настоящих Правил, а именно:"},{"n":"Статья 3.7","title":"","sub":[{"n":"а)","text":"при дорожно-транспортном происшествии;","lvl":1},{"n":"б)","text":"при вынужденной остановке в местах, где остановка запрещена (вынужденная остановка должна быть связана с технической неисправностью, не позволяющей дальнейшее движение);","lvl":1},{"n":"в)","text":"при ослеплении водителя светом фар;","lvl":1},{"n":"г)","text":"при буксировке (на буксируемом транспортном средстве);","lvl":1}],"text":"Аварийная сигнализация должна быть включена:"},{"n":"Статья 3.8","title":"","sub":[{"n":"а)","text":"для предупреждения других водителей о намерении произвести обгон вне населенных пунктов;","lvl":1},{"n":"б)","text":"в случаях, когда это необходимо для предотвращения дорожно-транспортного происшествия.","lvl":1}],"text":"Звуковые сигналы могут применяться только:"},{"n":"Статья 3.9","title":"","text":"В темное время суток и в условиях недостаточной видимости независимо от освещения дороги, а также в тоннелях на движущемся транспортном средстве должны быть включены фары дальнего или ближнего света. Дальний свет должен быть переключен на ближний в населенных пунктах, если дорога освещена. В светлое время суток на всех движущихся транспортных средствах (кроме велосипедов) с целью их обозначения должны включаться фары ближнего света или дневные ходовые огни."},{"h":"Глава IV. Обязанности пешеходов, велосипедистов"},{"n":"Статья 4.1","title":"","text":"Пешеходы должны двигаться по тротуарам или пешеходным переходам."},{"n":"Статья 4.2","title":"","text":"Пешеходам запрещено двигаться по дорогам, за исключением пешеходных переходов."},{"n":"Статья 4.3","title":"","sub":[{"n":"а)","text":"сотрудники ГИБДД;","lvl":1},{"n":"б)","text":"водители остановленных транспортных средств сотрудниками ГИБДД;","lvl":1},{"n":"в)","text":"сотрудники медицинских организаций при оказании медицинской помощи;","lvl":1},{"n":"г)","text":"сотрудники государственных организаций при проведении процессуальных действий, операций по ликвидации преступников.","lvl":1}],"text":"Не являются пешеходами следующие участники дорожного движения:"},{"n":"Статья 4.4","title":"","text":"В жилой зоне, то есть на территории, въезды на которую и выезды с которой обозначены знаком 1.36., движение пешеходов разрешается как по тротуарам, так и по проезжей части. В жилой зоне пешеходы имеют преимущество, при этом они не должны создавать на проезжей части необоснованные помехи для движения транспортных средств."},{"n":"Статья 4.5","title":"","text":"Движение велосипедистов в возрасте должно осуществляться по велосипедной, велопешеходной дорожкам, проезжей части велосипедной зоны или полосе для велосипедистов."},{"n":"Статья 4.6","title":"","sub":[{"n":"а)","text":"по правому краю проезжей части - в следующих случаях:","lvl":1},{"n":"","text":"отсутствуют велосипедная и велопешеходная дорожки, полоса для велосипедистов либо отсутствует возможность двигаться по ним;"},{"n":"","text":"габаритная ширина велосипеда превышает 1 м;"},{"n":"","text":"движение велосипедистов осуществляется в колоннах;"},{"n":"б)","text":"по обочине - в случае, если отсутствуют велосипедная и велопешеходная дорожки, полоса для велосипедистов либо отсутствует возможность двигаться по ним или по правому краю проезжей части;","lvl":1},{"n":"в)","text":"по тротуару или пешеходной дорожке - в случае, если отсутствуют велосипедная и велопешеходная дорожки, полоса для велосипедистов либо отсутствует возможность двигаться по ним, а также по правому краю проезжей части или обочине;","lvl":1}],"text":"Допускается движение велосипедистов:"},{"n":"Статья 4.7","title":"","text":"Выйдя на дорогу, пешеходы не должны задерживаться или останавливаться, если это не связано с обеспечением безопасности движения. Продолжать переход можно лишь убедившись в безопасности дальнейшего движения."},{"n":"Статья 4.8","title":"","text":"При приближении транспортных средств с включенным проблесковым маячком синего цвета (синего и красного цветов) и специальным звуковым сигналом пешеходы обязаны воздержаться от перехода дороги, а пешеходы, находящиеся на дороге, должны незамедлительно освободить проезжую часть"},{"n":"Статья 4.9","title":"","text":"На пешеходных переходах пешеходы могут выходить на дорогу после того, как оценят расстояние до приближающихся транспортных средств, их скорость и убедятся, что переход будет для них безопасен. При переходе дороги вне пешеходного перехода пешеходы, кроме того, не должны создавать помех для движения транспортных средств и выходить из-за стоящего транспортного средства или иного препятствия, ограничивающего обзорность, не убедившись в отсутствии приближающихся транспортных средств."},{"h":"Глава V. Сигналы светофора и регулировщика"},{"n":"Статья 5.1","title":"","text":"В светофорах применяются световые сигналы зеленого, желтого, красного и бело-лунного цвета."},{"n":"Статья 5.2","title":"","text":"Круглые сигналы светофора имеют следующие значения: ЗЕЛЕНЫЙ СИГНАЛ разрешает движение; ЖЕЛТЫЙ СИГНАЛ запрещает движение, кроме случаев, предусмотренных пунктом 6.14 Правил, и предупреждает о предстоящей смене сигналов; КРАСНЫЙ СИГНАЛ, в том числе мигающий, запрещает движение."},{"n":"Статья 5.3","title":"","text":"Сигналы регулировщика имеют следующие значения: РУКИ ВЫТЯНУТЫ В СТОРОНЫ ИЛИ ОПУЩЕНЫ: • со стороны левого и правого бока разрешено движение транспортным средствам прямо и направо, пешеходам разрешено переходить проезжую часть; • со стороны груди и спины движение всех транспортных средств и пешеходов запрещено. ПРАВАЯ РУКА ВЫТЯНУТА ВПЕРЕД: • со стороны левого бока разрешено движение транспортным средствам во всех направлениях; • со стороны груди всем транспортным средствам разрешено движение только направо; • со стороны правого бока и спины движение всех транспортных средств запрещено; • пешеходам разрешено переходить проезжую часть за спиной регулировщика. РУКА ПОДНЯТА ВВЕРХ: • движение всех транспортных средств и пешеходов запрещено во всех направлениях, кроме случаев, предусмотренных пунктом 5.6 Правил. Примечание: Регулировщик может подавать жестами рук и другие сигналы, понятные водителям и пешеходам. Для лучшей видимости сигналов регулировщик может применять жезл."},{"n":"Статья 5.4","title":"","text":"Требование об остановке транспортного средства подается с помощью громкоговорящего устройства или жестом руки, направленной на транспортное средство. Водитель должен остановиться в указанном ему месте."},{"n":"Статья 5.5","title":"","sub":[{"n":"а)","text":"на перекрестке - перед пересекаемой проезжей частью (с учетом иных положений Правил), не создавая помех пешеходам;","lvl":1},{"n":"б)","text":"перед железнодорожным переездом;","lvl":1},{"n":"в)","text":"в других местах - перед светофором или регулировщиком, не создавая помех транспортным средствам и пешеходам, движение которых разрешено.","lvl":1}],"text":"При запрещающем сигнале светофора или регулировщика водители должны остановиться перед стоп-линией, а при ее отсутствии:"},{"n":"Статья 5.6","title":"","text":"Водителям, которые при включении желтого сигнала или поднятии регулировщиком руки вверх не могут остановиться, не прибегая к экстренному торможению в местах, определяемых статьей 5.5 Правил, разрешается дальнейшее движение. Пешеходы и лица, использующие для передвижения средства индивидуальной мобильности, которые при подаче сигнала находились на проезжей части, должны освободить ее, а если это невозможно - остановиться на линии, разделяющей транспортные потоки противоположных направлений."},{"n":"Статья 5.7","title":"","text":"Участники дорожного движения должны выполнять требования сигналов и распоряжения регулировщика, даже если они противоречат сигналам светофора, требованиям дорожных знаков или разметки. В случае если значения сигналов светофора противоречат требованиям дорожных знаков приоритета, водители должны руководствоваться сигналами светофора."},{"h":"Глава VI. Начало движения, маневрирование"},{"n":"Статья 6.1","title":"","text":"Перед началом движения, перестроением, поворотом (разворотом) и остановкой водитель обязан подавать сигналы световыми указателями поворота соответствующего направления, в случае если они установлены на транспортном средстве. При выполнении маневра не должны создаваться опасность для движения, а также помехи другим участникам дорожного движения."},{"n":"Статья 6.2","title":"","text":"Подача сигнала указателями поворота должна производиться заблаговременно до начала выполнения маневра и прекращаться немедленно после его завершения. При этом сигнал не должен вводить в заблуждение других участников движения. Подача сигнала не дает водителю преимущества и не освобождает его от принятия мер предосторожности."},{"n":"Статья 6.3","title":"","text":"При выезде на дорогу с прилегающей территории водитель должен уступить дорогу транспортным средствам, лицам, использующим для передвижения средства индивидуальной мобильности, и пешеходам, движущимся по ней, а при съезде с дороги - пешеходам, велосипедистам путь движения которых он пересекает."},{"n":"Статья 6.4","title":"","text":"При перестроении водитель должен уступить дорогу транспортным средствам, движущимся попутно без изменения направления движения. При одновременном перестроении транспортных средств, движущихся попутно, водитель должен уступить дорогу транспортному средству, находящемуся справа."},{"n":"Статья 6.5","title":"","text":"Перед поворотом направо, налево или разворотом водитель обязан заблаговременно занять соответствующее крайнее положение на проезжей части, предназначенной для движения в данном направлении, кроме случаев, когда совершается поворот при въезде на перекресток, где организовано круговое движение."},{"n":"Статья 6.6","title":"","text":"Поворот должен осуществляться таким образом, чтобы при выезде с пересечения проезжих частей транспортное средство не оказалось на стороне встречного движения. При повороте направо транспортное средство должно двигаться по возможности ближе к правому краю проезжей части."},{"n":"Статья 6.7","title":"","text":"Если транспортное средство из-за своих габаритов или по другим причинам не может выполнить поворот с соблюдением требований статьи 6.5 Правил, допускается отступать от них при условии обеспечения безопасности движения и если это не создаст помех другим транспортным средствам."},{"n":"Статья 6.8","title":"","text":"При повороте налево или развороте вне перекрестка водитель безрельсового транспортного средства обязан уступить дорогу встречным транспортным средства. Если при развороте вне перекрестка ширина проезжей части недостаточна для выполнения маневра из крайнего левого положения, его допускается производить от правого края проезжей части (с правой обочины). При этом водитель должен уступить дорогу попутным и встречным транспортным средствам."},{"n":"Статья 6.9","title":"","text":"В случаях, когда траектории движения транспортных средств пересекаются, а очередность проезда не оговорена Правилами, дорогу должен уступить водитель, к которому транспортное средство приближается справа."},{"n":"Статья 6.10","title":"","text":"При наличии полосы торможения водитель, намеревающийся повернуть, должен своевременно перестроиться на эту полосу и снижать скорость только на ней. При наличии в месте въезда на дорогу полосы разгона водитель должен двигаться по ней и перестраиваться на соседнюю полосу, уступая дорогу транспортным средствам, движущимся по этой дороге."},{"n":"Статья 6.11","title":"","sub":[{"n":"а)","text":"на пешеходных переходах;","lvl":1},{"n":"б)","text":"в тоннелях;","lvl":1},{"n":"в)","text":"на мостах, путепроводах, эстакадах и под ними;","lvl":1},{"n":"г)","text":"на железнодорожных переездах;","lvl":1},{"n":"д)","text":"в местах с видимостью дороги хотя бы в одном направлении менее 100 м;","lvl":1},{"n":"е)","text":"в местах остановок маршрутных транспортных средств.","lvl":1}],"text":"Разворот запрещается:"},{"n":"Статья 6.12","title":"","text":"Движение транспортного средства задним ходом разрешается при условии, что этот маневр будет безопасен и не создаст помех другим участникам движения. При необходимости водитель должен прибегнуть к помощи других лиц. Движение задним ходом запрещается на перекрестках и в местах, где запрещен разворот согласно статье 6.11 Правил."},{"h":"Глава VII. Расположение транспортных средств на проезжей части"},{"n":"Статья 7.1","title":"","text":"Количество полос движения для безрельсовых транспортных средств определяется разметкой и (или) знаками 1.46, 1.47, 1.48, 1.49 а если их нет, то самими водителями с учетом ширины проезжей части, габаритов транспортных средств и необходимых интервалов между ними. При этом стороной, предназначенной для встречного движения на дорогах с двусторонним движением без разделительной полосы, считается половина ширины проезжей части, расположенная слева, не считая местных уширений проезжей части (переходно-скоростные полосы, дополнительные полосы на подъем, заездные карманы мест остановок маршрутных транспортных средств). На любых дорогах с двусторонним движением запрещается движение по полосе, предназначенной для встречного движения, если она отделена разделительной полосой, разметкой 2.1, 2.2."},{"n":"Статья 7.2","title":"","text":"На дорогах с двусторонним движением, имеющих четыре или более полосы, запрещается выезжать для обгона или объезда на полосу, предназначенную для встречного движения. На таких дорогах повороты налево или развороты могут выполняться на перекрестках и в других местах, где это не запрещено Правилами, знаками и (или) разметкой."},{"n":"Статья 7.3","title":"","text":"На дорогах с двусторонним движением, имеющих три полосы, обозначенные разметкой (за исключением разметки 2.3), из которых средняя используется для движения в обоих направлениях, разрешается выезжать на эту полосу только для обгона, объезда, поворота налево или разворота. Выезжать на крайнюю левую полосу, предназначенную для встречного движения, запрещается."},{"n":"Статья 7.4","title":"","text":"Вне населенных пунктов, а также в населенных пунктах на дорогах, обозначенных знаком 1.41 или где разрешено движение со скоростью более 80 км/ч, водители транспортных средств должны вести их по возможности ближе к правому краю проезжей части. Запрещается занимать левые полосы движения при свободных правых. В населенных пунктах с учетом требований настоящей статьи и иных статей Правил водители транспортных средств могут использовать наиболее удобную для них полосу движения. При интенсивном движении, когда все полосы движения заняты, менять полосу разрешается только для поворота налево или направо, разворота, остановки или объезда препятствия."},{"n":"Статья 7.5","title":"","text":"Если проезжая часть разделена на полосы линиями разметки, движение транспортных средств должно осуществляться строго по обозначенным полосам. Наезжать на прерывистые линии разметки разрешается лишь при перестроении."},{"n":"Статья 7.6","title":"","text":"При повороте на дорогу с реверсивным движением водитель должен вести транспортное средство таким образом, чтобы при выезде с пересечения проезжих частей транспортное средство заняло крайнюю правую полосу. Перестроение разрешается только после того, как водитель убедится, что движение в данном направлении разрешается и по другим полосам."},{"n":"Статья 7.7","title":"","text":"Запрещается движение транспортных средств по разделительным полосам и обочинам, тротуарам и пешеходным дорожкам (за исключением случаев, предусмотренных статьями настоящих Правил), а также движение механических транспортных средств (кроме мопедов) по полосам для велосипедистов. Запрещается движение механических транспортных средств по велосипедным и велопешеходным дорожкам. Допускается движение машин дорожно-эксплуатационных и коммунальных служб, а также подъезд по кратчайшему пути транспортных средств, подвозящих грузы к торговым и другим предприятиям и объектам, расположенным непосредственно у обочин, тротуаров или пешеходных дорожек, при отсутствии других возможностей подъезда. При этом должна быть обеспечена безопасность движения."},{"n":"Статья 7.8","title":"","text":"Водитель должен соблюдать такую дистанцию до движущегося впереди транспортного средства, которая позволила бы избежать столкновения, а также необходимый боковой интервал, обеспечивающий безопасность движения."},{"n":"Статья 7.9","title":"","text":"На дорогах с двусторонним движением при отсутствии разделительной полосы островки направляющие, островки безопасности, тумбы и элементы дорожных сооружений (опоры мостов, путепроводов и тому подобное), находящиеся на середине проезжей части, водитель должен объезжать справа, если знаки и разметка не предписывают иное."},{"h":"Глава VIII. Скорость движения"},{"n":"Статья 8.1","title":"","text":"Водитель должен вести транспортное средство со скоростью, не превышающей установленного ограничения, учитывая при этом интенсивность движения, особенности и состояние транспортного средства и груза, дорожные и метеорологические условия, в частности видимость в направлении движения. Скорость должна обеспечивать водителю возможность постоянного контроля за движением транспортного средства для выполнения требований Правил. При возникновении опасности для движения, которую водитель в состоянии обнаружить, он должен принять возможные меры к снижению скорости вплоть до остановки транспортного средства."},{"n":"Статья 8.2","title":"","text":"В населенных пунктах разрешается движение транспортных средств со скоростью не более 60 км/ч, а в жилых зонах, велосипедных зонах и на дворовых территориях не более 20 км/ч."},{"n":"Статья 8.3","title":"","sub":[{"n":"а)","text":"мотоциклам, легковым автомобилям и грузовым автомобилям на автомагистралях - со скоростью не более 110 км/ч, на остальных дорогах - не более 90 км/ч;","lvl":1},{"n":"б)","text":"автобусам, в которых места для сидения пассажиров оборудованы ремнями безопасности, предназначенным для перевозки исключительно сидящих пассажиров, - не более 90 км/ч, другим автобусам - не более 70 км/ч.","lvl":1}],"text":"Вне населенных пунктов разрешается движение:"},{"n":"Статья 8.4","title":"","sub":[{"n":"а)","text":"превышать максимальную скорость, определенную технической характеристикой транспортного средства;","lvl":1},{"n":"б)","text":"превышать скорость, указанную на знаке \"Ограничение максимальной скорости\";","lvl":1},{"n":"в)","text":"создавать помехи другим транспортным средствам, двигаясь без необходимости со слишком малой скоростью;","lvl":1},{"n":"г)","text":"резко тормозить, если это не требуется для предотвращения дорожно-транспортного происшествия.","lvl":1}],"text":"Водителю запрещается:"},{"h":"Глава IX. Обгон, опережение, встречный разъезд"},{"n":"Статья 9.1","title":"","text":"Прежде чем начать обгон, водитель обязан убедиться в том, что полоса движения, на которую он собирается выехать, свободна на достаточном для обгона расстоянии и в процессе обгона он не создаст опасности для движения и помех другим участникам дорожного движения."},{"n":"Статья 9.2","title":"","sub":[{"n":"а)","text":"транспортное средство, движущееся впереди, производит обгон или объезд препятствия;","lvl":1},{"n":"б)","text":"транспортное средство, движущееся впереди по той же полосе, подало сигнал поворота налево;","lvl":1},{"n":"в)","text":"следующее за ним транспортное средство начало обгон;","lvl":1},{"n":"г)","text":"по завершении обгона он не сможет, не создавая опасности для движения и помех обгоняемому транспортному средству, вернуться на ранее занимаемую полосу.","lvl":1}],"text":"Водителю запрещается выполнять обгон в случаях, если:"},{"n":"Статья 9.3","title":"","text":"Водителю обгоняемого транспортного средства запрещается препятствовать обгону посредством повышения скорости движения или иными действиями."},{"n":"Статья 9.4","title":"","sub":[{"n":"а)","text":"на регулируемых перекрестках, а также на нерегулируемых перекрестках при движении по дороге, не являющейся главной;","lvl":1},{"n":"б)","text":"на пешеходных переходах;","lvl":1},{"n":"в)","text":"на железнодорожных переездах и ближе чем за 100 метров перед ними;","lvl":1},{"n":"г)","text":"на мостах, путепроводах, эстакадах и под ними, а также в тоннелях","lvl":1},{"n":"д)","text":"в конце подъема, на опасных поворотах и на других участках с ограниченной видимостью.","lvl":1}],"text":"Обгон запрещен:"},{"n":"Статья 9.5","title":"","text":"В случае если вне населенных пунктов обгон или опережение тихоходного транспортного средства, крупногабаритного транспортного средства или транспортного средства, двигающегося со скоростью, не превышающей 30 км/ч, затруднены, водитель такого транспортного средства должен принять как можно правее, а при необходимости остановиться, чтобы пропустить следующие за ним транспортные средства."},{"n":"Статья 9.6","title":"","text":"В случае если встречный разъезд затруднен, водитель, на стороне которого имеется препятствие, должен уступить дорогу. Уступить дорогу при наличии препятствия на уклонах, обозначенных знаками 1.44, должен водитель транспортного средства, движущегося на спуск."},{"h":"Глава X. Остановка и стоянка"},{"n":"Статья 10.1","title":"","text":"Остановка и стоянка транспортных средств разрешаются на правой стороне дороги на обочине, а при ее отсутствии - на проезжей части у ее края и в случаях, установленных статьей 10.2 Правил, - на тротуаре."},{"n":"Статья 10.2","title":"","text":"Ставить транспортное средство разрешается в один ряд параллельно краю проезжей части. Способ постановки транспортного средства на стоянке (парковке) определяется знаком 1.40 и линиями дорожной разметки, знаком 1.40 с одной из табличек 1.26 - 1.34 и линиями дорожной разметки или без таковых. Сочетание знака 1.40 с одной из табличек 1.26 - 1.34, а также линиями дорожной разметки допускает постановку транспортного средства под углом к краю проезжей части в случае, если конфигурация (местное уширение) проезжей части допускает такое расположение. Стоянка на краю тротуара, граничащего с проезжей частью, разрешается только легковым автомобилям, мотоциклам и мопедам в местах, обозначенных знаком 1.40 с одной из табличек 1.26 - 1.34."},{"n":"Статья 10.3","title":"","sub":[{"n":"а)","text":"на железнодорожных переездах, в тоннелях, а также на эстакадах, мостах, путепроводах (если для движения в данном направлении имеется менее трех полос) и под ними;","lvl":1},{"n":"б)","text":"в местах, где расстояние между встречной полосой движения и остановившимся транспортным средством менее 3 м;","lvl":1},{"n":"в)","text":"на пешеходных переходах и ближе 5 м перед ними;","lvl":1},{"n":"г)","text":"на пересечении проезжих частей и ближе 5 м от края пересекаемой проезжей части, за исключением стороны напротив бокового проезда трехсторонних пересечений (перекрестков), имеющих сплошную линию разметки или разделительную полосу;","lvl":1},{"n":"д)","text":"на островках направляющих и островках безопасности.","lvl":1},{"n":"е)","text":"Запрещена парковка на местах для инвалидов, на служебных парковочных зонах государственных учреждений без соответствующих документов.","lvl":1}],"text":"Остановка запрещается:"},{"n":"Статья 10.4","title":"","sub":[{"n":"а)","text":"в местах, где запрещена остановка;","lvl":1},{"n":"б)","text":"вне населенных пунктов на проезжей части дорог, обозначенных знаком 1.3;","lvl":1},{"n":"в)","text":"ближе 50 м от железнодорожных переездов.","lvl":1}],"text":"Стоянка запрещается:"},{"n":"Статья 10.5","title":"","text":"Запрещается открывать двери транспортного средства, если это создаст помехи другим участникам дорожного движения."},{"n":"Статья 10.6","title":"","text":"Парковка ТС осуществляется на специально отведенных местах с специальными знаками и разметкой."},{"n":"Статья 10.7","title":"","text":"Запрещено блокировать въезды/выезды из парковочных зон, дворовых зон, гаражей, в случае парковки."},{"h":"Глава XI. Проезд перекрестков"},{"n":"Статья 11.1","title":"","text":"При повороте направо или налево водитель обязан уступить дорогу пешеходам и велосипедистам, пересекающим проезжую часть дороги, на которую он поворачивает."},{"n":"Статья 11.2","title":"","text":"Запрещается выезжать на перекресток, пересечение проезжих частей или участка перекрестка, обозначенного разметкой 2.5, если впереди по пути следования образовался затор, который вынудит водителя остановиться, создав препятствие для движения транспортных средств в поперечном направлении, за исключением поворота направо или налево в случаях, установленных настоящими Правилами."},{"n":"Статья 11.3","title":"","text":"Перекресток, где очередность движения определяется сигналами светофора или регулировщика, считается регулируемым. При неработающих светофорах или отсутствии регулировщика перекресток считается нерегулируемым, и водители обязаны руководствоваться правилами проезда нерегулируемых перекрестков и установленными на перекрестке знаками приоритета."},{"n":"Статья 11.4","title":"","text":"При повороте налево или развороте по зеленому сигналу светофора водитель транспортного средства обязан уступить дорогу транспортным средствам, движущимся со встречного направления прямо или направо."},{"n":"Статья 11.5","title":"","text":"Водитель, въехавший на перекресток при разрешающем сигнале светофора, должен выехать в намеченном направлении независимо от сигналов светофора на выходе с перекрестка. Однако, если на перекрестке перед светофорами, расположенными на пути следования водителя, имеются стоп-линии, водитель обязан руководствоваться сигналами каждого светофора."},{"n":"Статья 11.6","title":"","text":"При включении разрешающего сигнала светофора водитель обязан уступить дорогу транспортным средствам, завершающим движение через перекресток, и пешеходам, не закончившим переход проезжей части данного направления."},{"n":"Статья 11.7","title":"","text":"На перекрестке неравнозначных дорог водитель транспортного средства, движущегося по второстепенной дороге, должен уступить дорогу транспортным средствам, приближающимся по главной, независимо от направления их дальнейшего движения."},{"n":"Статья 11.8","title":"","text":"В случае, когда главная дорога на перекрестке меняет направление, водители, движущиеся по главной дороге, должны руководствоваться между собой правилами проезда перекрестков равнозначных дорог. Этими же правилами должны руководствоваться водители, движущиеся по второстепенным дорогам."},{"n":"Статья 11.9","title":"","text":"На перекрестке равнозначных дорог, за исключением случая, предусмотренного статьей 11.10 Правил, водитель транспортного средства обязан уступить дорогу транспортным средствам, приближающимся справа."},{"n":"Статья 11.10","title":"","text":"При въезде по дороге, не являющейся главной, на перекресток, на котором организовано круговое движение и который обозначен знаком 1.54, водитель транспортного средства обязан уступить дорогу транспортным средствам, движущимся по такому перекрестку."},{"n":"Статья 11.11","title":"","text":"При повороте налево или развороте водитель транспортного средства обязан уступить дорогу транспортным средствам, движущимся по равнозначной дороге со встречного направления прямо или направо."},{"n":"Статья 11.12","title":"","text":"Если водитель не может определить наличие покрытия на дороге (темное время суток, грязь, снег и тому подобное), а знаков приоритета нет, он должен считать, что находится на второстепенной дороге."},{"h":"Глава XII. Движение по автомагистралям, движение в жилых зонах"},{"n":"Статья 12.1","title":"","sub":[{"n":"а)","text":"движение пешеходов, лиц, домашних животных, велосипедов, мопедов, иных транспортных средств, скорость которых по технической характеристике или их состоянию менее 40 км/ч;","lvl":1},{"n":"б)","text":"движение грузовых автомобилей с разрешенной максимальной массой более 3,5 т далее второй полосы;","lvl":1},{"n":"в)","text":"остановка вне специальных площадок для стоянки, обозначенных знаком 1.40;","lvl":1},{"n":"в)","text":"разворот и въезд в технологические разрывы разделительной полосы;","lvl":1},{"n":"г)","text":"движение задним ходом.","lvl":1}],"text":"На автомагистралях запрещается:"},{"n":"Статья 12.2","title":"","text":"Требования статьи 12.1 Правил распространяются также на дороги, обозначенные “Дорога для автомобилей”"},{"n":"Статья 12.3","title":"","text":"В жилой зоне, то есть на территории, въезды на которую и выезды с которой обозначены знаками 1.36, движение пешеходов разрешается как по тротуарам, так и по проезжей части. В жилой зоне пешеходы имеют преимущество, при этом они не должны создавать на проезжей части необоснованные помехи для движения транспортных средств и лиц, использующих для передвижения средства индивидуальной мобильности."},{"n":"Статья 12.4","title":"","text":"Требования статей 12.1 - 12.3 Правил распространяются также и на дворовые территории."},{"h":"Глава XIII. Технические требования к транспортному средству"},{"n":"Статья 13.1","title":"","text":"Техническое состояние и оборудование транспортных средств, участвующих в дорожном движении, должны обеспечивать безопасность дорожного движения. Обязанность по поддержанию транспортных средств, участвующих в дорожном движении, в технически исправном состоянии возлагается на владельцев транспортных средств либо на лиц, эксплуатирующих транспортные средства."},{"n":"Статья 13.2","title":"","sub":[{"n":"а)","text":"отсутствии государственных регистрационных знаков;","lvl":1},{"n":"б)","text":"неисправности двигателя, его технического состояния менее 50% по техническому паспорту транспортного средства;","lvl":1},{"n":"в)","text":"прочих технических неисправностях, мешающих движению и создающих опасность, утвержденных постановлением Правительства Российской Федерации, Правительства Нобарской области.","lvl":1}],"text":"Запрещена эксплуатация транспортного средства при:"},{"n":"Статья 13.3","title":"","text":"Запрещена зеркальная тонировка Примечание: тонировка, поверхность которой способна образовывать оптические изображения предметов (в том числе источников света), отражая световые лучи."},{"n":"Статья 13.4","title":"","text":"Запрещена эксплуатация транспортного на котором установлена тонировка, более 75% на боковых передних и лобовом стеклах (в том числе запрещены цветные пленки)."},{"h":"Глава XIV. Пешеходные переходы и места остановок маршрутных транспортных средств, приоритет маршрутных транспортных средств"},{"n":"Статья 14.1","title":"","text":"Водитель транспортного средства, приближающегося к нерегулируемому пешеходному переходу (понятие аналогичное нерегулируемому перекрестку, обязан уступить дорогу пешеходам, переходящим дорогу или вступившим на проезжую часть (трамвайные пути) для осуществления перехода."},{"n":"Статья 14.2","title":"","text":"Если перед нерегулируемым пешеходным переходом остановилось или снизило скорость транспортное средство, то водители других транспортных средств, движущихся в том же направлении, также обязаны остановиться или снизить скорость. Продолжать движение разрешено с учетом требований статьи 14.1 Правил."},{"n":"Статья 14.3","title":"","text":"На регулируемых пешеходных переходах при включении разрешающего сигнала светофора водитель должен дать возможность пешеходам и лицам, использующим для передвижения средства индивидуальной мобильности, закончить пересечение проезжей части (трамвайных путей) соответствующего направления."},{"n":"Статья 14.4","title":"","text":"Запрещается въезжать на пешеходный переход, если за ним образовался затор, который вынудит водителя остановиться на пешеходном переходе."},{"n":"Статья 14.5","title":"","text":"Водитель должен уступить дорогу пешеходам, идущим к стоящему в месте остановки маршрутному транспортному средству или от него (со стороны дверей), если посадка и высадка производятся с проезжей части или с посадочной площадки, расположенной на ней."},{"n":"Статья 14.6","title":"","text":"На дорогах с полосой для маршрутных транспортных средств, обозначенных знаками и разметкой, запрещаются движение и остановка других транспортных средств на этой полосе, за исключением транспортных средств, используемых в качестве легкового такси с нанесенными на автомобиле знаками такси. На полосах для маршрутных транспортных средств разрешено движение велосипедистов в случае, если такая полоса располагается справа. Водители транспортных средств, допущенных к движению по полосам для маршрутных транспортных средств, при въезде на перекресток с такой полосы могут отступать от требований дорожных знаков 1.19 - 1.24, 1.46 - 1.49 для продолжения движения по такой полосе. Если эта полоса отделена от остальной проезжей части прерывистой линией разметки, то при поворотах транспортные средства должны перестраиваться на нее. Разрешается также в таких местах заезжать на эту полосу при въезде на дорогу и для посадки и высадки пассажиров у правого края проезжей части при условии, что это не создает помех маршрутным транспортным средствам."},{"n":"Статья 14.7","title":"","text":"В населенных пунктах водители должны уступать дорогу троллейбусам и автобусам, начинающим движение от обозначенного места остановки. Водители троллейбусов и автобусов могут начинать движение только после того, как убедятся, что им уступают дорогу."},{"h":"Глава XV. Положение об организации дорожного движения"},{"n":"Статья 15.1","title":"","text":"Сотрудники Государственной инспекции безопасности дорожного движения (далее - ГИБДД) могут регулировать дорожное движения в полной мере, показывая разрешенные и запрещенные направления движения."},{"n":"Статья 15.2","title":"","sub":[{"n":"15.2.1","text":"Сотрудники ГИБДД имеют право на остановку транспортного средства. Не допускается останавливать транспортные средства на участках дорог, где их остановка запрещена настоящими Правилами, за исключением случаев, когда такая остановка связана с необходимостью пресечения преступления, административного правонарушения, регулирования дорожного движения, предотвращения причинения вреда жизни, здоровью и (или) имуществу участников дорожного движения, а также случаев обозначения места остановки патрульным автомобилем с включенными специальными световыми сигналами, другими средствами регулирования и организации дорожного движения."}]},{"n":"Статья 15.3","title":"","sub":[{"n":"15.3.1","text":"Сотруднику ГИБДД разрешено применять все возможные меры, предусмотренные законом и соразмерные цели пресечения, в целях остановки транспортного средства, в случае неподчинения законному требованию сотрудника ГИБДД остановиться."}]},{"n":"Статья 15.4","title":"","text":"Водители, не подчинившиеся сотрудникам ГИБДД, несут ответственность согласно законодательству, а также настоящих Правил."},{"n":"Статья 15.5","title":"","sub":[{"n":"15.5.1","text":"Сотрудники ГИБДД ведут надзор в сфере безопасности дорожного движения. Выпускают соответствующие нормативно-правовые акты, регулирующие поведение на дороге и иные действия участников дорожного движения, касающиеся ведения сотрудников ГИБДД, в случае если эти нормативно-правовые акты не противоречат настоящим Правилам."}]},{"n":"Статья 15.6","title":"","sub":[{"n":"15.6.1","text":"Сотрудники ГИБДД уполномочены на осмотр, фиксацию дорожно-транспортного происшествия. Сотрудник ГИБДД выносит решения по результатам дорожно-транспортного происшествия. При ДТП Сотрудник ГИБДД:"},{"n":"а)","text":"устанавливает лиц, виновных в ДТП;","lvl":1},{"n":"б)","text":"привлекает к административной ответственности нарушителей настоящих Правил, виновных в аварии;","lvl":1},{"n":"в)","text":"оценивает физический ущерб нанесенный вследствие ДТП;","lvl":1},{"n":"г)","text":"взыскивает компенсацию частичную или полную, в зависимости от степени вины, с виновника(-ков) ДТП.","lvl":1},{"n":"","text":"Примечание: сотрудник выносит решение, опираясь на доказательства, имеющиеся у водителей, на место и расположение объектов ДТП, сотрудник основывается на настоящие Правила."}]},{"n":"Статья 15.7","title":"","sub":[{"n":"15.7.1","text":"ГИБДД—признается органом исполнительной власти в пределах Министерства внутренних дел Российской Федерации в сфере надзора за безопасностью дорожного движения. Постановления руководства ГИБДД обязательны к исполнению всем участникам дорожного движения, если они не противоречат настоящим Правилам."}]},{"n":"Статья 15.8","title":"","sub":[{"n":"15.8.1","text":"Сотрудники ГИБДД уполномочены на составление административных протоколов, постановлений, штрафов, и иных мер воздействия на нарушителей. Сотрудники ГИБДД ведут учет водительских удостоверений, имеют право выдавать и аннулировать водительские удостоверения в порядке, установленном законодательством."}]},{"n":"Статья 15.9","title":"","text":"Руководство ГИБДД имеет право на временную приостановку действия водительского удостоверения сроком не более 12 часов. Данное право реализуется через постановления Начальника ГИБДД или Заместителя Начальника ГИБДД."},{"n":"Статья 15.10","title":"","text":"Сотрудники ГИБДД ведут учет государственных регистрационных знаков, имеют право ставить государственные регистрационные знаки на транспортные средства."},{"n":"Статья 15.11","title":"","sub":[{"n":"15.11.1","text":"Сотрудники ГИБДД проводят оперативно-профилактические мероприятия на дорогах. Такие мероприятия санкционируются Начальником ГИБДД или Заместителем Начальника ГИБДД."}]},{"n":"Статья 15.12","title":"","sub":[{"n":"15.12.1","text":"Эвакуация транспортных средств, нарушающих 10 главу настоящих Правил осуществляется ГИБДД"},{"n":"15.12.2","text":"Эвакуация транспортных средств, с включенными проблесковыми маячками нарушающих 10 главу настоящих Правил запрещается, в случае когда нарушение главы 10 настоящих Правил связано с острой служебной необходимостью."},{"n":"15.12.3","text":"Эвакуация транспортных средств, с включенными проблесковыми маячками нарушающих 10 главу настоящих Правил разрешена, в случае если размещение транспорта несет серьезную угрозу безопасности дорожного движения."},{"n":"15.12.4","text":"Эвакуация транспортных средств, находящихся в пользовании или принадлежащих лицам обладающим неприкосновенностью или особым порядком привлечения к ответственности, разрешена. Запрещается проведение обыска, вскрытия, проникновения в транспортное средство."}]},{"n":"Статья 15.13","title":"","sub":[{"n":"1)","text":"используя данные жетона засекреченного сотрудника, заполняя протокол данными о транспортном средстве;","lvl":1},{"n":"2)","text":"оформляя постановление от имени Управления ГИБДД, взыскивая сумму штрафа с организации, в которой служит сотрудник.","lvl":1},{"n":"","text":"Порядок оформления протокола в отношении засекреченного сотрудника устанавливается совместным приказом МВД России и ФСБ России."},{"n":"","text":"Примечание: постановление подлежит официальной публикации. На исполнение постановления у Руководителей государственной организации 24 часа с момента официального опубликования постановления."}],"text":"В случае, если настоящие Правила были нарушены сотрудником государственной структуры, чья личность является государственной тайной и не подлежит разглашению, сотрудник ГИБДД оформляет протокол административного правонарушения в одном из следующих порядков:"},{"n":"Статья 15.14","title":"","sub":[{"n":"15.14.1","text":"Сотрудники ГИБДД проводят перекрытие дороги в установленном настоящими Правилами порядке."},{"n":"15.14.2","text":"Причины для перекрытия дороги:"},{"n":"а)","text":"ремонт дорожного полотна и /или объектов, к ней прилегающих;","lvl":1},{"n":"б)","text":"многочисленные нарушения законодательства РФ на определенном участке дороги, а также совершение действий, направленных на ликвидацию последствий массовых нарушений законодательства;","lvl":1},{"n":"в)","text":"специальные мероприятия, санкционированные Правительством Российской Федерации, Правительствами субъектов Российской Федерации;","lvl":1},{"n":"г)","text":"крупное дорожно-транспортное происшествие;","lvl":1},{"n":"д)","text":"оперативно-профилактическое мероприятие, санкционируемое начальником органа ГИБДД по субъекту или его заместителями;","lvl":1},{"n":"е)","text":"проведение плановых, аварийных работ дорог города и области;","lvl":1},{"n":"ж)","text":"внедрение/переключение временных схем организации дорожного движения.","lvl":1},{"n":"15.14.3","text":"Порядок проведения перекрытия дороги:"},{"n":"а)","text":"перекрытие санкционируется постановлением начальником органа ГИБДД или его заместителем, причиной, сроками, дежурством и экипажей ГИБДД на месте перекрытия;","lvl":1},{"n":"б)","text":"начало перекрытия дороги, требует от сотрудника ответственного за организацию перекрытия объявить об этом в новости государственного канала, оповестив граждан о перекрытии;","lvl":1},{"n":"г)","text":"ответственный сотрудник ГИБДД обязан поставить специальное транспортное средство поперёк дорожного полотна;","lvl":1},{"n":"д)","text":"окончание перекрытия санкционируется тем же органом, который его вводил, с обязательным демонтажом временных технических средств организации дорожного движения.","lvl":1},{"n":"15.14.4","text":"Водителю транспортного средства запрещено проезжать на дорожное полотно и объекты, к ней прилегающие, при проведении перекрытия дороги."},{"n":"15.14.5","text":"Сотруднику ГИБДД, проводящему перекрытие дороги, разрешено обращаться за помощью к другим силовым структурам."},{"n":"15.14.6","text":"Сотрудник ГИБДД, проводящий перекрытие дороги обязан показывать постановление, согласно которому он производит данное мероприятие следующим лицам:"},{"n":"а)","text":"сотрудникам Правительства Российской Федерации, Правительств субъектов Российской Федерации;","lvl":1},{"n":"б)","text":"журналистам средств массовой информации при предъявлении удостоверения журналиста.","lvl":1},{"n":"","text":"Примечание: сотрудник ГИБДД, проводящий перекрытие дороги не обязан предоставлять постановление лицам, не указанным в данной статье."}]},{"n":"Статья 15.15","title":"","sub":[{"n":"15.15.1","text":"Сотрудники ГИБДД уполномочены давать правовую оценку происходящим на дороге событиям. Сотрудники ГИБДД выносят решения, разрешают споры по поводу действий отдельных статей настоящих Правил. Толкование и разъяснение временных схем организации дорожного движения и режимов технических средств организации дорожного движения осуществляет ГИБДД . При коллизии приоритет имеют настоящие Правила и решения ГИБДД по безопасности."},{"n":"15.15.2","text":"Толкование настоящих Правил, противоречащее решению Конституционного Суда Российской Федерации, не применяется."}]},{"n":"Статья 15.16","title":"","sub":[{"n":"а)","text":"проведение теоретического экзамена, содержащего 15 вопросов по статьям Правил (Разрешается допустить только 2 ошибки);","lvl":1},{"n":"б)","text":"проведение практического экзамена, состоящего из выполнения элементов вождения на специальной территории и демонстрации навыков вождения в городских условиях;","lvl":1},{"n":"в)","text":"в случае успешной сдачи экзаменов обучающемуся выдается водительское удостоверение/дополняется пометкой, с предварительно выбранной категорией.","lvl":1},{"n":"","text":"Примечание: обучающийся должен быть старше 18 лет, иметь полный пакет документов (устанавливается постановлением управления ГИБДД)."}],"text":"Сотрудник ГИБДД выдает водительское удостоверение в следующем порядке:"},{"n":"Статья 15.17","title":"","text":"Исключительно сотрудники УГИБДД наделены правом выписать административный штраф за 9 главу Кодекса Об Административных Правонарушениях, если иное не установлено Кодексом об административных правонарушениях"},{"n":"Статья 15.18","title":"","text":"Специальный транспорт осуществляющий при помощи технических средств организации дорожного движения надзор за соблюдением настоящих правил выступающих за пределы габаритов транспортного средства (выдвижные камеры / радары) обязуются передвигаться в крайней правой полосе и включенными проблесковыми маячками."},{"n":"Статья 15.19","title":"","text":"Специальный транспорт осуществляющий при помощи технических средств организации дорожного движения надзор за соблюдением настоящих правил обязуются передвигаться с включенными проблесковыми маячками. Президент Российской Федерации Москва, Кремль 16 октября 2026 года № 45-ФЗ"}]};
